svg.script:
/* ================= EDIT ME ================= */
var CONFIG = {
  github: 'YOUR_GITHUB_USERNAME',
  // optional: list exact repo names to force what shows in "ML rabbit hole".
  // leave empty to auto-detect ML-ish repos by name / description / topics.
  mlRepos: [],
  goodreads: '',            // e.g. 'https://www.goodreads.com/user/show/12345-ayesha'
  reading: [
    // { title: 'Book title', author: 'Author', progress: 40 },
  ],
  recipe: {
    title: 'lebu cha (lemon tea)',
    serves: 2,
    time: '6 min',
    steep: 180,             // seconds, used by the timer
    ingredients: [
      '2 cups water',
      '1½ tsp loose black tea (or 2 tea bags)',
      '2 tsp sugar, or to taste',
      '½ lemon, juiced',
      '1 thin slice of ginger (optional)',
      'a pinch of black salt (optional)'
    ],
    steps: [
      'bring the water to a boil with the ginger.',
      'take it off the heat, add the tea and steep.',
      'strain into cups and stir in the sugar.',
      'squeeze in the lemon last, so it stays bright, not bitter.',
      'add the black salt if you like it the street-stall way.'
    ]
  }
};
/* =========================================== */

(function () {
  var XH = 'http://www.w3.org/1999/xhtml';
  function $(id) { return document.getElementById(id); }
  var root = $('root'), cmd = $('cmd'), out = $('out'), cur = $('cursor'),
      mode = $('mode'), modeBg = $('modebg'), sel = $('sel'), win = $('win'),
      boot = $('boot'), panel = $('panel'), ptitle = $('ptitle'), pbody = $('pbody');
  var job = 0, token = 0, isOpen = false, guesses = 0;

  /* ---------- helpers ---------- */
  function h(tag, attrs, kids) {
    var e = document.createElementNS(XH, tag);
    if (attrs) Object.keys(attrs).forEach(function (k) {
      if (k === 'text') e.textContent = attrs[k];
      else if (k === 'on') Object.keys(attrs.on).forEach(function (ev) { e.addEventListener(ev, attrs.on[ev]); });
      else e.setAttribute(k, attrs[k]);
    });
    (kids || []).forEach(function (c) {
      if (c == null || c === '') return;
      e.appendChild(typeof c === 'string' ? document.createTextNode(c) : c);
    });
    return e;
  }
  function clear(el) { while (el.firstChild) el.removeChild(el.firstChild); }
  function link(href, text, cls) {
    var a = h('a', { href: href, target: '_blank', rel: 'noopener', text: text });
    if (cls) a.setAttribute('class', cls);
    return a;
  }
  function hd(cmdText, extra) { return h('div', { class: 'hd' }, [h('b', { text: '❯ ' }), cmdText + (extra ? '  · ' + extra : '')]); }
  function setupCard(title, msg) { return h('div', { class: 'card' }, [h('div', { class: 'ttl', text: title }), h('div', { class: 'meta', text: msg })]); }
  function pad(n) { return (n < 10 ? '0' : '') + n; }
  function fmt(s) { return Math.floor(s / 60) + ':' + pad(s % 60); }
  function ago(iso) {
    var s = (Date.now() - new Date(iso).getTime()) / 1000;
    if (s < 60) return 'just now';
    var u = [[31536000, 'y'], [2592000, 'mo'], [86400, 'd'], [3600, 'h'], [60, 'm']];
    for (var i = 0; i < u.length; i++) if (s >= u[i][0]) return Math.floor(s / u[i][0]) + u[i][1] + ' ago';
  }

  /* ---------- terminal ---------- */
  function setMode(m) {
    mode.textContent = m;
    modeBg.setAttribute('class', m === 'INSERT' ? 'pill insert' : m === 'VIEW' ? 'pill view' : 'pill');
  }
  function say(t) {
    out.textContent = t;
    out.style.animation = 'none';
    requestAnimationFrame(function () { out.style.animation = ''; });
  }
  function placeCursor() {
    var w = 0;
    try { w = cmd.getComputedTextLength(); } catch (e) {}
    cur.setAttribute('x', 124 + w + (w ? 2 : 0));
  }
  function type(el, text, done, my) {
    var i = 0;
    (function step() {
      if (my !== undefined && my !== job) return;
      el.textContent = text.slice(0, i);
      if (el === cmd) placeCursor();
      if (i < text.length) { i++; setTimeout(step, 26 + Math.random() * 42); }
      else if (done) done();
    })();
  }
  function run(c, o, after) {
    var my = ++job;
    out.textContent = '';
    setMode('INSERT');
    type(cmd, c, function () {
      setTimeout(function () {
        if (my !== job) return;
        if (o) say(o);
        setMode(isOpen ? 'VIEW' : 'NORMAL');
        if (after) after();
      }, 160);
    }, my);
  }
  function onActivate(el, fn) {
    el.addEventListener('click', fn);
    el.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); fn(); }
    });
  }

  /* ---------- github ---------- */
  var cache = {};
  function gh(path) {
    if (cache[path]) return Promise.resolve(cache[path]);
    return fetch('https://api.github.com' + path, { headers: { Accept: 'application/vnd.github+json' } })
      .then(function (r) {
        if (r.status === 403 || r.status === 429) throw new Error('rate');
        if (r.status === 404) throw new Error('404');
        if (!r.ok) throw new Error('http');
        return r.json();
      })
      .then(function (j) { cache[path] = j; return j; });
  }
  function noUser(b) {
    if (CONFIG.github && CONFIG.github !== 'YOUR_GITHUB_USERNAME') return false;
    b.appendChild(setupCard('github username not set', 'set CONFIG.github at the top of the script in this file.'));
    say('who are you on github?');
    return true;
  }
  function ghError(b, e) {
    clear(b);
    var msg = e.message === 'rate' ? 'github rate limit hit (60 requests an hour). try again in a bit.'
            : e.message === '404' ? 'no github user called "' + CONFIG.github + '".'
            : 'couldn\'t reach github. check the connection.';
    b.appendChild(h('div', { class: 'muted', text: msg }));
    say('github said no.');
  }

  var ML_RE = /\b(ml|ai|llm|llms|gpt|nlp|rl|cnn|rnn|gan|bert|rag)\b|machine ?learning|deep ?learning|neural|torch|tensorflow|keras|sklearn|scikit|transformer|diffusion|classifier|classification|regression|prediction|kaggle|dataset|embedding|computer ?vision|mnist|hugging ?face/i;

  /* ---------- data ---------- */
  var NUKES = [
    { y: 1957, n: 'Kyshtym', p: 'Mayak, USSR', l: 6, d: 'a failed cooling system let a radioactive waste tank explode. kept secret for decades.' },
    { y: 1957, n: 'Windscale fire', p: 'Cumbria, UK', l: 5, d: 'a graphite reactor core caught fire and burned for days. milk from nearby farms was poured away.' },
    { y: 1961, n: 'SL-1', p: 'Idaho, USA', l: 4, d: 'a small army test reactor went critical when a control rod was pulled too far. three operators died.' },
    { y: 1979, n: 'Three Mile Island', p: 'Pennsylvania, USA', l: 5, d: 'a stuck valve and confusing instruments led to a partial meltdown. it reshaped US reactor rules.' },
    { y: 1986, n: 'Chernobyl', p: 'Pripyat, USSR (now Ukraine)', l: 7, d: 'a late-night safety test on reactor 4 ended in an explosion and fire. the exclusion zone is still there.' },
    { y: 1987, n: 'Goiânia', p: 'Goiás, Brazil', l: 5, d: 'scavengers opened an abandoned radiotherapy machine and its caesium-137 source spread through the city.' },
    { y: 2011, n: 'Fukushima Daiichi', p: 'Fukushima, Japan', l: 7, d: 'an earthquake and tsunami knocked out power for cooling, leading to three meltdowns.' }
  ];

  var FORTUNES = [
    ['opened one wikipedia tab about reactor cooling. it is now 3 a.m. and you know what a scram is.', 2],
    ['named a variable final_final_v2_ACTUAL.', 3],
    ['git push --force. on a friday. at 6 p.m.', 5],
    ['bought 4 new books. has not finished the last 4.', 1],
    ['trained a model for 6 hours. it predicts the mean.', 4],
    ['made cha. forgot the cha. made cha again. forgot that one too.', 2],
    ['read about Chernobyl right before bed. slept great. (lie)', 3],
    ['wrote "// TODO: fix later" a year ago. later has not arrived.', 4],
    ['17 tabs open. bookmarked none. trusts memory completely.', 3],
    ['fixed the failing test by deleting the test.', 5],
    ['said "quick question" before a 40-minute question.', 2],
    ['debugged for 2 hours. it was a missing comma.', 3],
    ['set lr=0.1 "just to see what happens". it happened.', 4],
    ['started a new side project instead of finishing the other six.', 3]
  ];

  /* ---------- panels ---------- */
  var R = {
    coding: function (b, t) {
      b.appendChild(hd('git log --latest-push'));
      if (noUser(b)) return;
      var wait = h('div', { class: 'muted', text: 'fetching your latest push…' });
      b.appendChild(wait);
      gh('/users/' + CONFIG.github + '/events/public?per_page=50').then(function (ev) {
        var p = ev.find(function (e) { return e.type === 'PushEvent'; });
        if (!p) return { none: true };
        var cs = (p.payload && p.payload.commits) || [];
        var list = cs.length
          ? Promise.resolve(cs.map(function (c) { return { sha: c.sha, msg: c.message }; }))
          : (p.payload && p.payload.head
              ? gh('/repos/' + p.repo.name + '/commits/' + p.payload.head)
                  .then(function (c) { return [{ sha: c.sha, msg: c.commit.message }]; })
                  .catch(function () { return []; })
              : Promise.resolve([]));
        return list.then(function (l) { return { p: p, list: l }; });
      }).then(function (d) {
        if (t !== token) return;
        b.removeChild(wait);
        if (d.none) {
          b.appendChild(h('div', { class: 'muted', text: 'no public pushes in the last 90 days. suspiciously quiet.' }));
          say('nothing pushed lately.');
          return;
        }
        var p = d.p, repo = p.repo.name, br = (p.payload.ref || '').replace('refs/heads/', '');
        b.appendChild(h('div', { class: 'card' }, [
          h('div', { class: 'row' }, [
            h('div', { class: 'ttl' }, [link('https://github.com/' + repo, repo)]),
            h('div', { class: 'meta', text: ago(p.created_at) })
          ]),
          h('div', { class: 'meta', text: (br ? 'branch ' + br + ' · ' : '') + new Date(p.created_at).toLocaleString() })
        ]));
        if (d.list.length) {
          b.appendChild(h('div', { class: 'sec', text: d.list.length + (d.list.length > 1 ? ' commits' : ' commit') }));
          d.list.slice(0, 10).forEach(function (c) {
            var sha = c.sha || '';
            b.appendChild(h('div', { class: 'c' }, [
              link('https://github.com/' + repo + '/commit/' + sha, sha.slice(0, 7), 'sha'),
              h('span', { text: (c.msg || '').split('\n')[0] })
            ]));
          });
        }
        b.appendChild(h('div', { class: 'meta', style: 'margin-top:16px' }, [link('https://github.com/' + CONFIG.github, 'github.com/' + CONFIG.github + ' →')]));
        say('pushed to ' + repo.split('/')[1] + ' ' + ago(p.created_at) + '.');
      }).catch(function (e) { if (t === token) ghError(b, e); });
    },

    ml: function (b, t) {
      b.appendChild(hd('ls ~/github | grep -i ml'));
      if (noUser(b)) return;
      var wait = h('div', { class: 'muted', text: 'digging through repos…' });
      b.appendChild(wait);
      gh('/users/' + CONFIG.github + '/repos?per_page=100&sort=pushed').then(function (rs) {
        if (t !== token) return;
        b.removeChild(wait);
        var pick = CONFIG.mlRepos && CONFIG.mlRepos.length
          ? rs.filter(function (r) { return CONFIG.mlRepos.indexOf(r.name) > -1; })
          : rs.filter(function (r) {
              var hay = [r.name, r.description || '', (r.topics || []).join(' ')].join(' ').replace(/[-_.\/]/g, ' ');
              return ML_RE.test(hay) || r.language === 'Jupyter Notebook';
            });
        if (!pick.length) {
          b.appendChild(h('div', { class: 'muted', text: 'no ML repos found yet. the rabbit hole is still being dug.' }));
          say('0 matches. for now.');
          return;
        }
        pick.slice(0, 12).forEach(function (r) {
          var meta = [r.language, r.stargazers_count ? '★ ' + r.stargazers_count : '', 'updated ' + ago(r.pushed_at)].filter(Boolean).join(' · ');
          b.appendChild(h('div', { class: 'card' }, [
            h('div', { class: 'ttl' }, [link(r.html_url, r.name)]),
            r.description ? h('div', { class: 'meta', style: 'color:var(--fg);opacity:.75', text: r.description }) : null,
            h('div', { class: 'meta', text: meta }),
            (r.topics || []).length ? h('div', {}, r.topics.slice(0, 5).map(function (tp) { return h('span', { class: 'tag', text: tp }); })) : null
          ]));
        });
        say(pick.length + ' repos deep. send help.');
      }).catch(function (e) { if (t === token) ghError(b, e); });
    },

    reading: function (b) {
      var L = CONFIG.reading || [];
      b.appendChild(hd('cat ~/shelf/currently-reading', L.length + (L.length === 1 ? ' book' : ' books')));
      if (!L.length) b.appendChild(setupCard('no books on the shelf yet', 'add your current reads to CONFIG.reading at the top of the script.'));
      L.forEach(function (bk) {
        var pct = typeof bk.progress === 'number' ? Math.max(0, Math.min(100, bk.progress)) : null;
        b.appendChild(h('div', { class: 'card' }, [
          h('div', { class: 'row' }, [
            h('div', { class: 'ttl', text: bk.title }),
            pct !== null ? h('div', { class: 'meta', text: pct + '%' }) : null
          ]),
          h('div', { class: 'meta', text: 'by ' + (bk.author || 'unknown') }),
          pct !== null ? h('div', { class: 'bar' }, [h('i', { style: 'width:' + pct + '%' })]) : null
        ]));
      });
      if (CONFIG.goodreads) b.appendChild(h('div', { class: 'meta', style: 'margin-top:16px' }, [link(CONFIG.goodreads, 'goodreads profile →')]));
      say(L.length ? L.length + ' books open at once. like the tabs.' : 'shelf is empty. suspicious.');
    },

    cha: function (b) {
      var r = CONFIG.recipe;
      b.appendChild(hd('cat lemon_tea.recipe'));
      b.appendChild(h('div', { class: 'row' }, [
        h('div', { class: 'ttl', style: 'font-size:14px', text: r.title }),
        h('div', { class: 'meta', text: 'serves ' + r.serves + ' · ' + r.time })
      ]));
      b.appendChild(h('div', { class: 'sec', text: 'ingredients' }));
      b.appendChild(h('ul', {}, r.ingredients.map(function (x) { return h('li', { text: x }); })));
      b.appendChild(h('div', { class: 'sec', text: 'method' }));
      b.appendChild(h('ol', {}, r.steps.map(function (x) { return h('li', { text: x }); })));
      b.appendChild(h('button', {
        id: 'steepbtn', class: 'btn',
        text: steep.iv ? 'steeping… ' + fmt(steep.left) : 'start steeping (' + fmt(r.steep) + ')',
        on: { click: startSteep }
      }));
      say('kettle\'s on. everything else can wait.');
    },

    nuke: function (b) {
      b.appendChild(hd('less ines_incidents.log', NUKES.length + ' entries'));
      NUKES.forEach(function (x) {
        var segs = [];
        for (var i = 1; i <= 7; i++) segs.push(h('i', { class: i <= x.l ? 'f' : '' }));
        b.appendChild(h('div', { class: 'card' }, [
          h('div', { class: 'row' }, [
            h('div', { class: 'ttl' }, [h('span', { class: 'yr', text: String(x.y) }), x.n]),
            h('div', { class: 'row', style: 'gap:8px' }, [h('span', { class: 'ines' }, segs), h('span', { class: 'meta', style: 'margin:0', text: 'INES ' + x.l })])
          ]),
          h('div', { class: 'meta', text: x.p }),
          h('div', { class: 'meta', style: 'color:var(--fg);opacity:.75;margin-top:4px', text: x.d })
        ]));
      });
      b.appendChild(h('div', { class: 'meta', style: 'margin-top:10px', text: 'INES is the international nuclear event scale, from 1 (anomaly) to 7 (major accident).' }));
      say('researching. purely academically.');
    },

    huh: function (b) {
      var i = Math.floor(Math.random() * FORTUNES.length);
      var txt = h('div', { class: 'fortune' }), meta = h('span', { class: 'meta', style: 'margin:0' }), reg = h('span', { class: 'ines' });
      function show() {
        txt.textContent = FORTUNES[i][0];
        meta.textContent = 'decision #' + (i + 1) + ' of ' + FORTUNES.length + ' · regret';
        clear(reg);
        for (var k = 1; k <= 5; k++) reg.appendChild(h('i', { class: k <= FORTUNES[i][1] ? 'f' : '' }));
      }
      show();
      b.appendChild(hd('fortune --questionable'));
      b.appendChild(txt);
      b.appendChild(h('div', { class: 'row', style: 'justify-content:flex-start;gap:10px' }, [meta, reg]));
      b.appendChild(h('button', { class: 'btn', text: 'another one', on: { click: function () {
        var j;
        do { j = Math.floor(Math.random() * FORTUNES.length); } while (j === i);
        i = j; show();
        say('no regrets. (some regrets.)');
      } } }));
      say('no comment.');
    }
  };

  /* ---------- tea timer ---------- */
  var steep = { left: 0, iv: null };
  function updStatus() {
    sel.textContent = '6 items · ' + (steep.iv ? 'steeping ' + fmt(steep.left) : '17 tabs');
  }
  function startSteep() {
    if (steep.iv) return;
    steep.left = CONFIG.recipe.steep;
    root.classList.add('brewing');
    updStatus();
    say('steeping. ' + fmt(steep.left) + ' on the clock.');
    steep.iv = setInterval(function () {
      steep.left--;
      updStatus();
      var btn = document.getElementById('steepbtn');
      if (btn) btn.textContent = 'steeping… ' + fmt(steep.left);
      if (steep.left <= 0) {
        clearInterval(steep.iv); steep.iv = null;
        root.classList.remove('brewing');
        updStatus();
        if (btn) btn.textContent = 'steep another (' + fmt(CONFIG.recipe.steep) + ')';
        say('cha is ready. drink it before it goes cold.');
      }
    }, 1000);
  }

  /* ---------- open / close ---------- */
  var icons = Array.prototype.slice.call(document.querySelectorAll('.icon'));
  function openPanel(el) {
    token++;
    isOpen = true;
    icons.forEach(function (i) { i.classList.remove('on'); });
    el.classList.add('on');
    ptitle.textContent = '~/desktop/' + el.getAttribute('data-name');
    clear(pbody);
    pbody.scrollTop = 0;
    R[el.getAttribute('data-k')](pbody, token);
    panel.classList.add('open');
    setMode('VIEW');
  }
  function closePanel() {
    if (!isOpen) return;
    token++;
    isOpen = false;
    panel.classList.remove('open');
    icons.forEach(function (i) { i.classList.remove('on'); });
    run(':q', 'closed. it will be reopened.');
  }

  icons.forEach(function (el) {
    onActivate(el, function () {
      if (isOpen) return;
      run(el.getAttribute('data-cmd'), '', function () { openPanel(el); });
    });
  });
  onActivate($('pclose'), closePanel);
  $('backdrop').addEventListener('click', closePanel);
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') closePanel(); });

  document.querySelectorAll('.light').forEach(function (el) {
    el.addEventListener('click', function () {
      run(el.getAttribute('data-cmd'), el.getAttribute('data-msg'), function () {
        win.classList.remove('shake');
        requestAnimationFrame(function () { win.classList.add('shake'); });
      });
    });
  });

  var tabs = Array.prototype.slice.call(document.querySelectorAll('.tab'));
  onActivate($('guess'), function () {
    guesses++;
    var g = guesses;
    run('shuf -n 4 tabs.txt', 'guess #' + g + '. confidence: ' + (g > 3 ? 'nonexistent.' : 'low.'), function () {
      tabs.forEach(function (t) { t.classList.remove('lit'); });
      var pool = tabs.slice();
      for (var i = 0; i < 4; i++) pool.splice(Math.floor(Math.random() * pool.length), 1)[0].classList.add('lit');
    });
  });

  /* ---------- boot + clock ---------- */
  boot.textContent = '';
  setTimeout(function () { type(boot, 'ls ~/desktop'); }, 300);

  var D = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  var M = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  function tick() {
    var d = new Date();
    $('clock').textContent = D[d.getDay()] + ' ' + d.getDate() + ' ' + M[d.getMonth()] + '  ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
  }
  tick(); setInterval(tick, 15000);
})();
